insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/ko/3973', E'ko', 18, E'꽃 놀이를 한다면 추천해요!! 이시카와, 토야마, 후쿠이 호쿠리쿠지방의 3현의 절경 벚꽃 5선', E'호쿠리쿠신칸선이 개통되어서 접근성이 좋아진 호쿠리쿠지방! 봄에 방문한다면 꼭 보고오고싶은 벚꽃 명소를 소개합니다.\n\n호쿠리쿠 지방이란 이시카와현、토야마현、후쿠이현의 세개의 현을 의미합니다. 일본의 혼슈의 북쪽에 위치하고있고, 동해를 접하고 있는 지역이죠. 예전엔 도쿄로부터의 교통수단이 적었지만, 호쿠리쿠신칸센이 개통되며 도쿄에서 가기 훨씬 수월해졌습니다. 덕분에 많은 관광객이 호쿠리쿠를 방문하고있죠.\n\n올 봄은 그런 주목을 받고있는 지역인 호쿠리쿠의 세개의 현으로 발걸음을 옮기셔서, 분홍색으로 물들은 벚꽃을 즐기시면 어떨까요?\n\n2018년의 호쿠리쿠지방지역의 개화일과 만개일의 정보는 아래와 같습니다. 2019년 예상정보가 공개되는 대로 정보를 갱신하도록 하겠습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17639.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17634.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17635.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17638.webp"]'::jsonb, E'2019-01-25'::timestamptz, null),
(E'https://matcha-jp.com/ko/25753', E'ko', 19, E'[나가노/야마나시] 가을 여행 - 단풍 구경 완벽 가이드 | 놓칠 수 없는 추천 명소', E'가을의 나가노와 야마나시는 후지산, 호수, 유서 깊은 사찰, 도시 경관, 그리고 단풍을 한 곳에서 즐길 수 있는 최고의 명소입니다. 맑은 공기와 상쾌한 기후 덕분이죠. 산책, 사진 촬영, 독서, 맛있는 음식까지 더해져 완벽한 가을 주말 여행지가 될 것입니다.\n\n일본의 가을 하면 빼놓을 수 없는 것이 바로 선명한 단풍입니다. 나가노현과 야마나시현은 도쿄 수도권에서 접근성이 좋고, 관광지 간 이동도 비교적 편리하여 가을 단풍을 즐기고 싶은 여행객에게 최고의 여행지입니다.\n\n나가노현과 야마나시현에는 후지산, 호수, 유서 깊은 사찰, 그리고 유서 깊은 마을 풍경이 어우러진 아름다운 단풍 명소가 곳곳에 있습니다. 아라쿠라야마 센겐 공원, 후지카와구치 호수, 젠코지, 구모바 연못, 구 가루이자와 등 인기 관광지를 중심으로 단풍의 매력과 추천 명소를 자세히 소개해 드리겠습니다.\n\n아라쿠라야마 센겐 공원은 봄에는 벚꽃 명소로도 유명합니다. 오층탑과 후지산을 배경으로 만개한 벚꽃을 감상할 수 있습니다. 가을에는 붉고 노란 단풍나무와 은행나무가 오층탑을 감싸며 눈 덮인 후지산과 아름다운 대조를 이룹니다. 국내외에서 많은 관광객이 찾아와 사계절의 아름다운 풍경을 감상할 수 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243455.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243456.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243457.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243458.webp"]'::jsonb, E'2025-09-05'::timestamptz, null),
(E'https://matcha-jp.com/ko/7843', E'ko', 19, E'후지산의 기슭・야마나카 호에서 꼭 하고싶은 여덟가지', E'야마나카 호는 야마나시현・후지산의 기슭에 있는 호수입니다. 후지 5호 중에서도 가장 면적이 넓고 후지산이 가장 가까이 보이는 호수로도 유명하여 국내외 많은 관광객이 찾습니다. 아름다운 자연경관을 즐길 수 있을 뿐만 아니라, 유람선이나 낚시등의 레저, 온천시설, 플라워 파크 등 가볼 만한 곳이 많습니다. 그런 야마나카 호를 즐기는 방법을 소개합니다.\n\n야마나카호 (山中湖) 란, 야마나시현의 야마나카코무라 지역에 위치한 호수입니다. 후지산 밑에 자리잡은 다섯 곳의 호수「후지 5호 (富士五湖)」(※1) 중에서도 가장 큰 최대 6.57제곱 킬로미터의 면적을 가진, 후지산에서 가장 가까운 호수이기도 합니다.\n\n호수주변에는 후지산이 아름답게 보이는 것으로 유명하여, 야마나카호에는 많은 관광객들이 찾아옵니다. 2013년에는「후지산 신앙의 대상과 예술의 원천」의 구성자산 중 하나로 유네스코 세계문화유산에 등재되었습니다.\n\n※1：후지5호……모토스코 호수 (本栖湖), 쇼지코 호수 (精進湖), 사이코 호수 (西湖), 카와구치 호수 (河口湖), 야마나카코 호수 ( 山中湖) 의 다섯 곳을 가리킴', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/27-84656.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/27-84655.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/27-84657.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/06-85392.webp"]'::jsonb, E'2019-10-24'::timestamptz, E'후지 이에 아케'),
(E'https://matcha-jp.com/ko/20731', E'ko', 19, E'가와구치 호의 연간 기온은? 후지산 관광 시즌도 해설', E'후지산 기슭에 펼쳐진 가와구치 호는 도쿄에서 자동차로 불과 2시간 거리에 자리하고 있으며 아름다운 풍경이 매력적인 곳입니다. 여행을 간다면 벚꽃과 단풍을 즐기기 위한 최고의 시기와 기온에 맞는 복장 선택도 궁금하기 마련입니다. 이번에는 가와구치 호수의 기온과 날씨, 복장에 대한 정보를 정리해 소개합니다.\n\n또한 가와구치 호 지역의 여름은 짧고 따뜻하며 습도가 높은 것이 특징이며, 흐려지기 쉬워 갑작스러운 비가 내릴 수 있습니다. 한편 겨울은 춥고 눈이 내리기 쉽지만 맑은 날이 많습니다. 1년 간의 기온 변화는 최저 기온 -7℃~최고 기온 26℃까지로 -11℃ 이하나 29℃ 이상이 되는 일은 드뭅니다.\n\n쾌적한 기후 덕분에 관광에도 적합합니다. 다만 산간 지역에 가깝기 때문에 하루 사이에도 날씨가 변하기 쉽고 일교차도 큽니다. 따라서 계절에 맞는 복장을 준비하고 상의나 모자 등을 지참하는 것을 추천합니다.\n\n7월 하순부터 9월 초순의 가와구치 호는 기온이 온난하여 야외에 적합합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/05/20-180721.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/06-145116.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/27-189997.webp","https://resources.matcha-jp.com/resize/720x2000/2021/11/05-117889.webp"]'::jsonb, E'2025-01-02'::timestamptz, null),
(E'https://matcha-jp.com/ko/5900', E'ko', 20, E'일본의 현재와 과거를 넘나드는 볼거리 가득한 나가노 시오지리 관광 가이드', E'나가노 시오지리 시는 맛있는 신슈 와인과 멋진 칠기로 유명한 곳입니다. 거리 서남부에 있는 \'나라이주쿠\'는 일본의 옛 모습이 고스란히 남아 있는 지역으로 다양한 볼거리를 제공합니다! 시오지리를 마음껏 즐길 수 있는 추천 관광 스폿을 소개할게요.\n\n나가노 현 마쓰모토 시(松本市)에서 열차로 10~20분 거리에 있는 시오지리 시(塩尻市)는 맛있는 신슈(信州) 와인의 탄생지이자 칠기로 잘 알려져 있는 곳이에요. 거리 서남부에 있는 \'나라이주쿠(奈良井宿)\'는 에도 시대때부터 에도와 교토를 잇는 나카센도(中山道)의 중간 지점에 자리한 숙박지로, 옛 풍경을 고스란히 보존하고 있어 국가의 중요 전통적 건조물군 보존지구로 등록되어 있습니다.\n\n현재 나라이주쿠에는 칠기 상점, 료칸, 식당, 박물관 등이 있는데 마치 일본의 과거로 돌아간 듯한 정취를 느끼며 걷기만 해도 즐거워지는 거리지요.\n\n나가노를 여행할 계획이라면 맛있는 와인, 일본의 옛 풍경, 그리고 아름다운 칠기를 마음껏 즐길 수 있는 시오지리에 잠시 들러 보는 건 어떨까요? 이 기사에서는 시오지리의 거리를 1. 시오지리 역 주변, 2. 칠기로 유명한 기소히라사와(木曽平沢), 3. 옛 거리를 보존하고 있는 나라이주쿠(奈良井宿), 이렇게 세 지역으로 나누어 소개하려고 해요. 지역마다 각기 다른 매력과 체험, 관광 스폿이 있는 시오지리의 다양한 모습을 발견하러 지금부터 함께 떠나 볼까요~?', E'["https://resources.matcha-jp.com/resize/720x2000/2018/03/20-50837.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/26-51145.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/20-50841.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/23-51072.webp"]'::jsonb, E'2018-04-03'::timestamptz, E'마쓰모토시'),
(E'https://matcha-jp.com/ko/25615', E'ko', 20, E'[나가노] 기타시가의 톱 3 스키장 가이드: 스키, 온천, 눈원숭이 관찰!', E'도쿄에서 기타시가현의 3대 스키 리조트까지! 초보자부터 상급자까지 모두 즐길 수 있는 코스와 폭신한 파우더 스노우를 만끽하고, 스키 후에는 온천과 향토 음식을 즐기며 휴식을 취하세요. 가나구야 료칸에서 지브리풍 건축물과 "규유 준레이" 온천 투어를 즐기고, 눈원숭이를 관찰하고, 겨울 자연 산책을 즐겨보세요. 이 가이드가 완벽한 겨울 여행 가이드입니다.\n\n겨울이 찾아오면 기타시가 지역은 일본 전역의 스키어와 스노보더들을 끌어들입니다. 도쿄에서 쉽게 접근할 수 있는 이 지역에는 초보자부터 상급자까지 즐길 수 있는 세 곳의 주요 스키장이 있습니다. 바로 기타시가 고마루야마 스키장, X-JAM 다카이 후지 스키장 & 요마세 온천 스키장, 그리고 류오 스키 파크입니다. 부모와 자녀가 처음 스키를 경험하는 것부터 상급자를 위한 프리스타일 스키까지, 이 지역을 즐길 수 있는 다양한 방법이 있습니다. 이 글에서는 기타시가의 세 곳 주요 스키장에 대한 종합적인 가이드를 제공하며, 교통, 숙박, 스키 체험, 설질의 차이, 그리고 슬로프에서 하루를 보낸 후 즐길 수 있는 맛있는 음식과 온천까지 다룹니다.\n\n기차 이용 시: 도쿄역에서 신칸센을 타고 나가노역까지 약 1시간 30분 소요됩니다. 나가노역에서 JR 또는 사철을 이용하여 가장 가까운 역으로 이동하실 수 있습니다. 변화하는 풍경을 감상하며 편안한 기차 여행을 즐겨보세요.\n\n고속버스를 이용하시는 경우, 도쿄역과 신주쿠역에서 직행 셔틀버스가 운행되며, 각 스키장으로 바로 가는 버스도 있습니다. 짐이 많거나 운전에 자신이 없는 분들에게 편리하며, 도착 후 바로 스키를 즐길 수 있다는 장점도 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241618.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241617.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241621.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241620.webp"]'::jsonb, E'2025-08-19'::timestamptz, null),
(E'https://matcha-jp.com/ko/7485', E'ko', 20, E'「가루이자와 호시노 에이리어 하루니레 테라스」와 그 주변에서 즐길 수 있는 8가지', E'가루이자와의 호시노 에이리어에 있는「하루니레 테라스」에는 분위기 좋은 카페나 지역의 상품들을 취급하는 가게들이 늘어서, 가루이자와에서 사는 기분으로 가루이자와를 만끽할 수 있습니다. 추천 가게나 맛집, 액티비티를 소개합니다.\n\n「하루니레 테라스 (ハルニレテラス)」는 방문하신 분들이 지역의 여유로운 생활과 풍부한 자연을 만끽할 수 있는 장소로써가루이자와 호시노 에이리어 내에 만들어졌습니다. 2009년 오픈한 이후, 가루이자와의 인기 관광지로 사랑받고 있습니다.\n\n가루이자와에서 유명한 료칸「호시노야 가루이자와 (星のや軽井沢)」도「하루니레 테라스」와 인접 해 있습니다.\n\n「하루니레」란 느릅나무를 뜻합니다. 시설은 느릅나무가 빽빽히 들어선 강변에 지어져 있습니다. 지면으로부터 2미터 정도의 높이에 설치된 우드데크 위에 상점들이 늘어 서 있어, 나무 사이사이를 걷는 듯한 느낌으로 산책을 즐길 수 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78860.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/29-78163.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/13-79486.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/29-78112.webp"]'::jsonb, E'2019-06-18'::timestamptz, E'가루이자와'),
(E'https://matcha-jp.com/ko/1375', E'ko', 21, E'기후는 어떤 곳인가요? ー지리・기후편ー', E'여러분은 「기후(岐阜)현」을 알고 계신가요?기후현은 일본의 거의 중간에 위치한 산과 강으로 둘러싸인 풍부한 자연환경을 가진 지역입니다. 도쿄나 교토의 중간 지점에 있으며 나고야(名古屋)에서 약간 북쪽에 있습니다.\n\n기후현은 일본의 거의 중간에 위치한 산과 강으로 둘러싸인 풍부한 자연환경을 가진 지역입니다. 도쿄나 교토의 중간 지점에 있으며 나고야(名古屋)에서 약간 북쪽에 있습니다.\n\n대자연과 옛부터 이어진 문화, 지금도 남아있는 오래된 민가 등, 훌륭한 관광자원을 가진 기후현은 일본을 찾아온 여행객분에게는 아직 그 매력을 잘 모르시죠.\n\n이번에는 기후현의 「기후(気候)」에 주목하여 계절마다 즐길 수 있는 것을 소개하겠습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/11/14-131886.webp","https://resources.matcha-jp.com/resize/720x2000/2022/11/14-131887.webp","https://resources.matcha-jp.com/resize/720x2000/2022/11/14-131888.webp","https://resources.matcha-jp.com/resize/720x2000/2022/11/14-131889.webp"]'::jsonb, E'2018-05-17'::timestamptz, E'기후시'),
(E'https://matcha-jp.com/ko/20151', E'ko', 21, E'나고야에서 2시간만에 갈 수 있는 「물과 오도리의 마을」군 카미하치만을 즐긴다', E'나고야에서 약 2시간이면 갈 수 있는 인기 관광지 기후현군 카미시. 죠카마치에서의 먹거리 걷기, 역사를 느끼는 마을 걷기, 그리고 군상 오도리와 청류 나가라가와의 아름다운 물에 치유되면서, 풍치가 있는 마을을 즐길 수 있습니다. 이번에는 그런 군상에 있는 추천 관광 명소를 소개합니다.\n\n기후현 군 카미시는 자연과 역사가 조화를 이루는 동해 지역 중에서도 매우 매력적인 관광지 중 하나입니다. 아름다운 초록, 청류 나가라강, 그리고 군상 하치만의 성시에 남는 낡은 거리를 즐길 수 있는 것을 비롯해, 여름의 강 놀이, 은어 낚시나 래프팅, 겨울의 스노 스포츠 등이 충실한 액티비티 왕국이기도 합니다. 그리고 무엇보다 유명한 군상의 여름의 풍물시라고 하면, 일본 3대 분무의 하나 「군상 오도리」입니다. 매년 여름에 개최되며, 관광객들도 현지인들과 함께 춤을 즐기는 것으로 알려져 있습니다. 춤을 즐기는 것과 동시에 성시에서는 많은 마을 걸음 음식이나 음식점도 있으므로, 관광에 온 사람들을 매료합니다. 이번은 군상시의 중심부, 군상 하치만의 에리어에 스포트를 맞아, 알려지지 않은 매력을 소개해 갑니다.\n\n우선 군 카미하치만의 입구 「군 카미하치만역」 군상 하치만까지의 액세스에 대해서는 나중에 소개합니다만, 만약 철도로 군상 하치만에 오게 되면 처음으로 보는 것이 군상 하치만역이 됩니다. 춤 제등이 매달려, 정취를 느낄 수 있는 외관입니다.\n\n역에서 군 카미하타만의 성시까지는 걸어갈 수 있습니다만, 순환 버스나 렌터사이클을 추천합니다. 버스라고 약 10분입니다만, 버스의 시간은 한정되어 있으므로, 만약 날씨가 좋으면 렌터사이클로 군상의 바람을 느끼면서 성시를 향하는 것도 즐기는 방법의 하나입니다. 렌터사이클은 1일 빌려 1,000엔 입니다. (3시간까지라면 500엔)', E'["https://resources.matcha-jp.com/resize/720x2000/2024/06/21-184593.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/27-217451.webp","https://resources.matcha-jp.com/resize/720x2000/2024/06/21-184597.webp","https://resources.matcha-jp.com/resize/720x2000/2024/06/21-184598.webp"]'::jsonb, E'2024-06-07'::timestamptz, null),
(E'https://matcha-jp.com/ko/25405', E'ko', 21, E'[기후현] 그림책 속 세계로 여행하세요: 시라카와고, 신호타카, 히다 마을의 원래 일본 풍경을 만나보세요', E'동화 속 풍경을 연상시키는 삼각 지붕의 집들이 늘어선 시라카와고, 북알프스의 웅장한 절경을 자랑하는 신호타카, 그리고 옛 일본의 삶을 체험할 수 있는 히다 마을. 자연과 전통이 살아 숨 쉬는 히다 지역으로 따뜻한 여행을 떠나 향수와 감동을 느껴보는 건 어떠세요?\n\n어린 시절 그림책에서 본 삼각형 지붕의 작은 집이 기억나시나요? 눈 덮인 굴뚝에서 따뜻한 연기가 피어오르는 가운데 홀로 서 있던 그 집을 보고 따뜻함을 느꼈던 기억이 있으신가요? 기후현 히다 지방에는 오늘날까지도 "동화 속 집"을 연상시키는 풍경이 소중하게 보존되어 있습니다.\n\n이번에는 시간이 부드럽고 향수 어린 분위기로 흐르는 세 곳을 소개합니다. 세계문화유산인 시라카와고, 북알프스의 아름다운 전망을 감상할 수 있는 신호타카, 그리고 전통적인 일본 생활을 체험할 수 있는 히다노사토입니다.\n\n시라카와고는 일본을 대표하는 갓쇼즈쿠리 마을 중 하나로 세계문화유산에 등재되어 있습니다. 마치 손을 맞잡은 듯한 모습의 초가지붕은 "갓쇼즈쿠리"라고 불리며, 눈이 많이 내리는 지역에서만 찾아볼 수 있는 독창적인 전통 건축 양식을 자랑합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/18-239133.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/18-239137.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/18-239151.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/18-239152.webp"]'::jsonb, E'2025-07-18'::timestamptz, E'시라카와고'),
(E'https://matcha-jp.com/ko/10255', E'ko', 22, E'도쿄 나고야에서 하마마츠로, 필수 방문 코스와 명물 먹거리를 1박 2일로 만끽해 보자', E'도쿄나 나고야에서 신칸센으로 갈 수 있는 시즈오카현의 도시 하마마츠. 꽃들의 낙원 \'하마마츠 플라워 파크\'와 전세계의 악기를 전시한 \'하마마츠 악기 박물관\' 등 볼거리가 풍부합니다. 하마마츠를 즐기는 방법과 장어, 교자만두 등 먹거리를 소개합니다!\n\n시즈오카현의 중심 도시·하마마츠시. 도쿄나 나고야에서 신칸센으로 갈 수 있어요. 하마마츠에 도착하면 전철이나 버스를 타고 주변 관광지를 돌아 봅시다.\n\n하마마츠는 자연과 역사, 음악, 테크놀로지에 관련된 다양한 명소가 있습니다. 하마마츠 만두를 비롯한 명물 맛집도 빼놓을 수 없죠!\n\n악기와 교자만두의 거리·하마마츠를 1박 2일로 돌아보는 관광 플랜을 소개합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110205.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110228.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110229.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110206.webp"]'::jsonb, E'2020-12-22'::timestamptz, null),
(E'https://matcha-jp.com/ko/10569', E'ko', 22, E'하마마츠, 정원, 가든, 플라워, 파크, 하마나코, 관광', E'일조시간이 전국 최고 수준인 하마마츠. 온난한 기후가 원예를 향한 천혜의 환경으로, 특히 하마나코 주변에는 서양식 정원부터 일본 정원까지 다양한 아름다운 정원이 있습니다. 각각 운치가 다른 시설과 꽃들을 즐길 수 있어, 여러 곳을 돌아보는 것도 추천합니다. 이번에는 하마나코 주변에 있는 정원의 매력을 소개해 보겠습니다.\n\n※이 기사는 시즈오카 하마마츠의 관광 사이트「Meet Japan Through Hamamatsu,」로부터 허락을 받고 기재한 것입니다.\n\n일조시간이 전국 최고수준인 하마마츠. 온난한 기후가 원예를 향한 천혜의 환경으로, 특히 하마나코 주변에는 서양식 정원부터 일본 정원까지 다양한 아름다운 정원이 있습니다.\n\n각각 운치가 다른 시설과 꽃들을 즐길 수 있어, 여러 곳을 돌아보는 것도 추천합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2021/06/09-114675.webp","https://resources.matcha-jp.com/resize/720x2000/2021/06/09-114676.webp","https://resources.matcha-jp.com/resize/720x2000/2021/06/09-114677.webp","https://resources.matcha-jp.com/resize/720x2000/2021/06/09-114678.webp"]'::jsonb, E'2021-06-12'::timestamptz, null),
(E'https://matcha-jp.com/ko/10541', E'ko', 22, E'절경 ・ 하마나호 주변의 추천 명소 소개 ~ 음식과 자전거도!', E'하마마츠에서 빼놓을 수 없는 관광명소는 하마나코 호수. 하마나호는 시즈오카 현 하마마츠 시와 고사이 시에 걸쳐 있는 둘레 114 킬로미터의 호수로, 기수호로는 일본 제일의 둘레 길이, 면적은 일본에서 10 번째의 크기를 자랑합니다.\n\n다테야마지 지역은 마을 이름의 유래가 된 사원 「다테야마지」, 음식점이나 기념품 가게, 당일치기 온천 등이 모이는 전국적으로 지명도가 높은 온천가에 가세해 유원지 「하마나코 파루파루」나 「하마나코 가든 파크」 「하마마츠 플라워 파크」등의 레저 명소도 많이 있어, 하마마츠에서도 인기의 관광지입니다. 하마마츠 역에서 노선버스로 한번에 갈 수 있습니다. 또, 뭐니뭐니해도 다테야마지 지역에서는 크루즈나 호수의 상공을 건너는 로프웨이, 사이클링 등으로 하마나호의 아름다움을 마음껏 즐길 수 있습니다.\n\n하마나호의 경치를 호상에서 즐길 수 있는 것이 \'하마나호 유람선\'입니다.\n\n다테야마지 지역과 강 건너에 있는 미카가히 지역을 잇는 \'세토 항로\'(편도 30분 1,000엔 ※왕복은 무제한으로 1,800엔)가, 1일 3왕복편 운항과 간잔지항 또는 플라워파크 항에서 출발해 승선했던 각 항구로 돌아오는 \'다테야마지 항로\' (30분 주유 1,000엔)가, 1일 3편을 운항하고 있습니다(※시기에 따라 다를 수 있음).', E'["https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114409.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114410.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114411.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114412.webp"]'::jsonb, E'2021-06-03'::timestamptz, null),
(E'https://matcha-jp.com/ko/3551', E'ko', 23, E'아이치현 나고야시 관광 가이드. 가는 방법, 명소, 기념품 정보 등', E'아이치현은 일본의 거의 중앙에 위치한 자치체예요. 나고야시는 그런 아이치현의 서부에 있답니다. 나고야라고 한다면 역시 독특한 식문화가 발달한 지역으로 유명해요. 나고야에서 태어난 특징적인 메뉴를 「나고야메시(なごやめし/밥)」라 부르머, 「히츠마부시(ひつまぶし)」나 「미소 카츠(味噌カツ)」등이 그 대표로 알려져 있어요. 이번에는, 그런 매력이 넘치는 나고야로 가는 방법, 시내의 교통 정보, 추천 스폿 등의 관광 정보를 정리했습니다.\n\n아이치현(愛知県)은 일본의 거의 중앙에 위치한 자치체에요. 나고야시는 그런 아이치현의 서부에 있답니다.\n\n나고야라고 한다면 독특한 식문화가 발달한 마을로 유명해요. 나고야에서 태어난 특징적인 메뉴를 「나고야메시(なごやめし/밥)」이라 부르며, 「히츠마부시(ひつまぶし)」나 「미소카츠(味噌カツ)」 등이 그 대표로 알려져 있습니다. 최근에는 이 음식을 즐기기 위해 나고야를 찾는 관광객도 늘고 있답니다.\n\n또, 역사적인 가치도 있는 장소입니다. 예를 들면 「아츠타 신궁(熱田神宮)」에선 일본 신화에 등장하는 일본 무존(武尊/야마토타케루노 미코토)이 가지고 있었다고 전해지는 보검 쿠사나기노 츠루기(草薙御劔)를 모시고 있지요.', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/30-12868.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/14-9180.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/14-9178.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/14-9182.webp"]'::jsonb, E'2018-07-20'::timestamptz, E'나고야시'),
(E'https://matcha-jp.com/ko/6436', E'ko', 23, E'나고야 완전 가이드〜추천하는 관광지 10곳, 맛집, 추천 경로', E'일본에서도 손 꼽히는 대도시, 나고야. 금의 물고기 장식이 빛나는 나고야성, 멋진 야경을 연출하는「오아시스21」, 일본정원「도쿠가와엔」등, 매력만점의 나고야 인기 관광지와 나고야의 매력을 물씬 느낄 수 있는 나고야 먹거리 등. 관광정보를 정리하여 소개합니다！\n\n도쿄 (東京)와 오사카 (大阪)에 이어 일본 3대도시로, 일본의 딱 중앙에 위치한 나고야 (名古屋).「도요타자동차」의 본사가 있는 것으로 유명한 아이치현 (愛知県)의 중심도시입니다.\n\n교통의 요지인 나고야역 주변은 최근 재개발을 통해 고층빌딩이 속속이 들어서 근대적인 분위기를 풍깁니다. 관광명소가 비교적 밀집해있기 때문에 하루에 둘러볼 수 있는 것이 나고야의 매력입니다.\n\n이런 나고야에서 꼭 들러보고 싶은 관광지를 엄선하였습니다. 마지막에는 추천 경로와 교통편을 소개하오니 여행하실 때 참고로 해주세요.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/28-61398.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/27-61347.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/18-60925.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/26-61340.webp"]'::jsonb, E'2019-02-18'::timestamptz, E'나고야시'),
(E'https://matcha-jp.com/ko/7258', E'ko', 23, E'【나고야】시장, 아침장, 상점가! 현지의 숨은 명소와 맛집 투어', E'대도시・나고야에도, 아침장과 상점가, 시장등 현지의 분위기를 즐길 수 있는 장소가 있습니다. 이번에는 현지인이 쇼핑하는 상점가나 거리의 인기 맛집, 오래된 다방의 명물 메뉴등, 나고야의 인정미를 들여다 볼 수 있는 장소를 소개합니다!\n\n시장이나 아침장, 그리고 상점가는 지방에 사는 일본인에게 있어서 친근한 쇼핑 장소입니다.\n\n본 기사에서는, 시장에서 해산물을 맛보며, 아침 장에서 수제 잡화를 찾아다니고, 붐비는 상점가에서 맛집을 탐방하는등 평소와 다른 나고야를 즐기는 법을 소개합니다. 리얼한 나고야를 체험해 봅시다!\n\n나고야역에서 도보 10분정도의 거리에 위치한 「야나기바시 중앙시장 마루나카 식품 센터」.4000평 정도의 부지에 300개정도의 점포가 있어 해산물 ,야채, 김 ,조리기구등의 가게가 모여있는, 일본에서 손꼽는 규모의 민간 시장입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74421.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74422.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74400.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74406.webp"]'::jsonb, E'2019-04-22'::timestamptz, null),
(E'https://matcha-jp.com/ko/21736', E'ko', 24, E'[미에] 나고야에서 바로 이동! 고자이쇼 로프웨이는 미에현의 숨은 절경 명소', E'고자이쇼 로프웨이는 나고야에서 접근성이 용이해 당일 여행에 최적입니다. 미에현과 시가현의 현 경계에 걸쳐 있는 스즈카 산맥 거의 중앙에 있는 고사이쇼산에서 바라보는 웅장한 경치와 하이킹을 즐길 수 있습니다. 이번 기사에서는 고자이쇼 로프웨이에 대한 자세한 정보와 주변의 관광 명소, 맛집, 온천에 대해 소개합니다.\n\n1959년에 개통한 전체 길이 약 2킬로미터의 로프웨이로 고자이쇼다케(표고 1,212미터)와 유노야마 온천가를 연결합니다. 편도 약 15분이므로 느긋하게 공중 산책을 즐길 수 있습니다.\n\n개통 당시에는 세계 최대의 로프웨이 중 하나였으며 고자이쇼 로프웨이의 지주인 백철탑의 높이는 일본 제일을 자랑합니다.\n\n나고야 역에서도 접근하기 쉽고 직통 버스를 사용하면 약 1시간 만에 도착할 수 있습니다. 자세한 이동 방법은 기사 마지막에 정리해 두었으니 꼭 확인해 주세요.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/17-203129.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/17-203151.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/24-198657.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/17-203133.webp"]'::jsonb, E'2024-10-29'::timestamptz, null),
(E'https://matcha-jp.com/ko/21726', E'ko', 24, E'[미에] 이세시마 관광에 편리한 ‘도바 시사이드 호텔’의 매력을 소개! 주변 관광 명소 포함', E'이세시마 관광을 한다면 도바 시사이드 호텔을 추천합니다. 이세 신궁과 도바 수족관, 미키모토 진주섬 등 유명한 명소에도 쉽게 갈 수 있습니다. 이번 기사에서는 충실한 서비스를 갖추고 있는 도바 시사이드 호텔의 매력이나 주변 관광 명소, 인기 맛집을 소개합니다.\n\n아름다운 바다와 더불어 이세에비, 마쓰자카규 등의 훌륭한 먹거리도 유명해 많은 사람들의 사랑을 받고 있습니다. 나아가 2000년 이상의 역사를 자랑하는 이세 신궁이나 명물 도바 수족관 같은 관광 명소도 빼놓을 수 없습니다.\n\n또한 아마(해녀)(※)의 전통과 양식 진주 문화도 이 지역만의 독특한 특색입니다. 알아가다보면 그 심오한 매력에 마음을 빼앗길지도 모릅니다. ※아마……바다에 잠수해 조개류 등을 채취하는 것을 직업으로 하는 사람\n\n미에현은 바다에 접해 있어 풍부한 해산물로 잘 알려져 있습니다. 특히 이세에비나 아노리 복어, 그리고 해녀가 잡는 전복도 유명합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/23-198486.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/22-198366.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/24-198546.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/24-198542.webp"]'::jsonb, E'2024-10-28'::timestamptz, E'이세시'),
(E'https://matcha-jp.com/ko/6127', E'ko', 24, E'이세・도바의 자연과 먹거리를 만끽하자! 센트레아에서 출발하는 작은 여행', E'나고야 근교에 있는 공항, 센트레아에서 파워스폿으로 유명한 Ise Jingu가 있는 이세・도바 지역으로 향하는 배가 있다는 사실을 알고 계신가요? 버스와 전철이 아닌, 배로 이동하는 1박 2일의 이세・도바 여행은 색다른 묘미를 찾을 수 있을 거예요. 이 여행에서 경험할 수 있는 이세・도바의 자연과 문화 특색을 MATCHA 라이터의 체험담과 함께 소개합니다!\n\n이세만(伊勢湾)이 자리 잡고 있는 미에현(三重県)은 예로부터 해로가 중요한 지위를 차지했으며 현재, 이세만(伊勢湾) 위에는 페리로 연결되는 해상 국도가 있어요.\n\n현 내의 유명 관광지 하면 가장 먼저 떠오르는 곳이 Ise Jingu(伊勢神宮)인데요, 한번 보면 잊을 수 없는 아름다운 경관을 자랑하는 도바만(鳥羽湾)도 함께 방문하면 문화와 자연을 모두 즐기며 인상 깊은 추억을 남길 수 있을 거예요.\n\n이번 기사에는 합리적인 세트 티켓을 이용하여 센트레아 나고야 중부국제공항(セントレア中部国際空港)에서 해상 교통인 고속선을 타고 이세만(伊勢湾)을 향하면서 이세(伊勢)와 도바(鳥羽)의 볼거리를 돌아보는 1박 2일의 코스를 소개할게요. 심신을 힐링하는 여행을 떠나볼까요!', E'["https://resources.matcha-jp.com/resize/720x2000/2018/05/23-54633.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/23-54634.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/23-54635.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/23-54636.webp"]'::jsonb, E'2018-06-19'::timestamptz, E'이세 지구'),
(E'https://matcha-jp.com/ko/9308', E'ko', 25, E'【2023】 간사이에서 인기! 대형 아울렛 쇼핑몰 8선 | 오사카에서도 좋은 액세스!', E'오사카를 중심으로 한 간사이 지역에는 쇼핑을 즐길 수 있는 대형 아울렛과 쇼핑몰이 많이 있습니다. 이번 기사에서는, 오사카에서 액세스도 양호한, 아울렛과 쇼핑몰을 8곳을 소개합니다. 각 점포에서 주목하고 싶은 추천 브랜드와 가는 법, 최신 정보도 전달합니다!\n\n간사이 지역에는 신사이바시스지(心斎橋筋) 상점가와 우메다(梅田) 백화점이 있는 오사카를 비롯해, 쇼핑을 즐길 수 있는 곳이 많이 있습니다.\n\n그 중에서도 이번에는 간사이에서 인기 대형 아울렛과 쇼핑몰 8곳을 소개합니다! 이득인 상품이 다양하게 있는 곳부터, 오사카 시내에서 가기 쉬운 곳까지 소개드리니 간사이에서 쇼핑을 할 예정이 있는 분은 꼭 체크해 봐 주세요.\n\n간사이의 아울렛과 쇼핑몰은 도시의 중심이 아닌 교외에 있는 것이 일반적입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/01/13-133733.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95575.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134033.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134036.webp"]'::jsonb, E'2023-02-15'::timestamptz, null),
(E'https://matcha-jp.com/ko/1365', E'ko', 25, E'[일본여행 토막상식] 관서(칸사이) 지방 (関西地方)', E'<strong>관서 지방</strong>(関西地方. 칸사이 치호)이란, 여행객의 출입을 관리하고 있던 관소*(関所.세키쇼)라 불리는 곳으로부터 <strong>서쪽 방향에 위치한 지역</strong>의 호칭입니다.\n\n관서 지방(関西地方. 칸사이 치호)이란, 여행객의 출입을 관리하고 있던 관소*(関所.세키쇼)라 불리는 곳으로부터 서쪽 방향에 위치한 지역의 호칭입니다. 시와 마을의 집합체로 도도부현(都道府県 : 도쿄「도」, 홋카이「도」, 오사카・쿄토「부」, 「현」의 총칭)보다도 넓은 범위의 지역을 가리키며, 지도로 봤을 때 혼슈(本州)(일본의 중심부에 있는 제일 큰 섬)의 중서부에 있습니다.\n\n*관소가 있던 시기는 8세기부터 18세기 무렵까지. 지금의 미에현, 기후현, 후쿠이현 등에 있었다고 한다.\n\n관서(칸사이) 지방에는, 오사카부・쿄토부・효고현・나라현・시가현・와카야마현의 2부 4현이 있습니다. 관서 지방과 똑같은 2부 4현에 미에현(三重県)이 추가되면 「킨키 지방(近畿地方)」이라는 다른 명칭도 있어서, 단체나 기업명에 「킨키」라는 이름이 보이는 경우가 많을 수도 있습니다. 그러나 그런 단체도 해외 용으로 KANSAI로 이름을 쓰는 곳이 많아, 일본 국외에서 이 지역은 주로 「칸사이(関西)」로 알려져 있습니다.', E'["https://resources.matcha-jp.com/archive_files/jp/2015/11/kansai_map_20151106.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/28-128706.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/28-128707.webp"]'::jsonb, E'2016-02-04'::timestamptz, null),
(E'https://matcha-jp.com/ko/2645', E'ko', 26, E'교토에 왔다면 꼭 가야 할 관광 명소 10선(킨카쿠지, 료안지 등)', E'역사 깊은 신사불각이 많은 인기 관광지・교토. 킨카쿠지, 긴카쿠지, 키요미즈데라, 료안지, 아라시야마 등. 꼭 가보셨으면 하는 관광 명소를 열 곳 소개해 드릴게요!\n\n794년부터 긴 세월 동안 일본의 수도였던 교토는 그 당시의 마을과 전통문화의 신비롭고 침착한 분위기가 남아 있답니다.\n\n방문한 사람들의 마음을 달래는 마을에는 오중탑(五重塔)이 있는 토우지(東寺)부터 킨카쿠지(金閣寺)와 긴카쿠지(銀閣寺), 키요미즈데라(清水寺)와 카미가모 신사(上賀茂神社), 시모가모 신사(下鴨神社)처럼 세계유산으로 등록된 많은 신사불각이 있어요. 그 중 료안지(龍安寺)나 텐류지(天龍寺) 등에서는 감동적인 정원도 볼 수 있답니다.\n\n게다가 쿄(京/교토)의 부엌이라고도 불리는 니시키 이치바(錦市場)를 구경하고 계절이 물씬 느껴지는 쿄 요리를 맛보고 나왔다면, 마을을 걷는 마이코(舞妓/춤 기생)들의 모습에 문득 뒤를 돌게 되겠지요. 이번에는, 매력이 끊이질 않는 교토를 소개해 드릴게요!', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123642.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123643.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123644.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123658.webp"]'::jsonb, E'2017-03-05'::timestamptz, E'아라시야마'),
(E'https://matcha-jp.com/ko/24939', E'ko', 26, E'15개의 미쉐린 가이드 교토 레스토랑, 온라인 예약 가능', E'교토에서 최고의 일본 요리를 경험하세요—이 15개 미쉐린 스타 레스토랑 중 한 곳에서 온라인 예약이 가능합니다.\n\n교토는 우아하고 세련된 식사 경험의 중심지로, 미쉐린 가이드에서 많은 레스토랑이 인정받는 것은 놀라운 일이 아닙니다. 전통적인 요리 스타일을 지키면서 현대적인 영향을 받아들이는 교토의 노력이 일본 전역과 전 세계에서 방문객을 계속 끌어들이고 있습니다.\n\n이하의 레스토랑들은 미쉐린 가이드에서 높은 평가를 받은 곳들입니다. 교토에서 기억에 남을 맛있는 경험을 위해 이 중 한 곳을 방문해 보세요.\n\n전통적인 교토 가옥 안에 숨겨진 엔유안 코바야시는 미쉐린 별이 반짝이는 가이세키 및 튀김 요리를 우아하고 매력적인 환경에서 제공합니다. 각 코스는 리듬과 목적을 가지고 정성스럽게 구성되어, 시작부터 끝까지 기대와 기쁨을 점차 높여줍니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233908.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233910.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233912.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233914.webp"]'::jsonb, E'2025-08-05'::timestamptz, null),
(E'https://matcha-jp.com/ko/21665', E'ko', 26, E'【교토 말차】10대 필수 방문 명소, 말차 성지 순례 여행', E'말차의 고향 교토에 오면, 여기서 마주하는 모든 푸른 색이 오래된 차향을 발산합니다. 아름다운 우지 지역에서부터 교토 시내의 작은 골목 깊숙한 곳까지, 각 찻집마다 독특한 매력과 이야기가 있습니다. 이번에 선정한 10개의 인기 말차 전문점. 100년 이상의 전통을 자랑하는 오래된 집부터 창의적인 새 찻집까지, 각 가게는 독특한 말차 경험을 제공합니다. 이번 인기 포켓 리스트를 따라가며 말차 성지의 환상적인 디저트를 함께 즐겨보세요!\n\n교토 거리에서 산책하며, 각 찻집마다 독특한 역사와 이야기가 숨겨져 있는 듯해 어떤 가게를 선택해야 할지 망설이게 됩니다.\n\n이번에는 우지와 교토 시내의 인기 말차 전문점 10곳을 소개합니다. 전통적인 고전 찻집부터 독특한 현대 찻집까지, 모두 말차를 맛볼 수 있는 훌륭한 선택입니다. 이번 말차 성지순례 여행을 함께하며 교토의 독특한 차 문화의 깊이를 느껴보세요.\n\n사진 제공: PRTimes 본격적인 소개에 앞서 우지 차에 대한 작은 지식을 알아볼까요? 우지는 일본의 가장 중요한 말차 재배지 중 하나로, 말차의 발상지로 여겨집니다. 그 역사는 800년 전의 가마쿠라 시대로 거슬러 올라가며, 당시에 영서 스님이 중국에서 차 씨앗을 가져와 고산사의 명혜 스님이 우지 지역에 이식했습니다. 우지 강의 안개와 온화한 기후는 차 나무 재배에 매우 적합하여, 우지는 점차 일본 차의 중요한 생산지로 자리 잡았습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/14-197498.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/19-198102.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/14-197501.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/14-197500.webp"]'::jsonb, E'2024-09-25'::timestamptz, E'우지'),
(E'https://matcha-jp.com/ko/1901', E'ko', 27, E'【2023】오사카 신사이바시에서 추천 쇼핑 명소! 패션이나 음식점, 기념품까지', E'오사카에서 쇼핑한다면 신사이바시・도톤보리에! 식료품, 의류, 약국이 늘어선 큰 상점가는 비도 무섭지 않습니다. 이 기사에서는, 스타일별로 추천의 점포나 교통 수단을 자세하게 소개합니다. 지도 링크도 붙어 있으므로 쉽게 찾을 수 있습니다.\n\n這是離大阪觀光據點難波和道頓堀較近的心齋橋。這裡有大阪具有代表性的商店街「心齋橋筋商店街」。 오사카의 관광 거점인 난바와 도톤보리에서도 가까운 신사이바시. 이곳은 오사카를 대표하는 상가입니다.\n\n신사이바시 상가의 전체 길이는 약 600m. 앞뒤로 이어지는 다른 상가도 포함하면 약 2킬로미터에 걸친 상가가 됩니다. 약국, 화장품점, 면세점, 100엔 숍, 캐릭터 숍, 레스토랑, 커피숍 등이 있어, 원하는 것은 모두 여기서 살 수 있다고 해도 과언이 아닙니다.\n\n이 기사에서는 신사이바시 상점가에는 어떤 가게가 있는지 장르별로 소개합니다! 기사의 마지막에는 상가에의 교통 수단도 써 있으므로, 이것을 읽으면 미아도 무서워 없어져요!', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61550.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61551.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61552.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1447.webp"]'::jsonb, E'2016-12-08'::timestamptz, E'오사카시'),
(E'https://matcha-jp.com/ko/1931', E'ko', 27, E'「난바역」완전 가이드 6개의 노선, 접근하기 쉬운 오사카 관광지를 철저히 소개!', E'어디로 가도 편리한 오사카 관광의 거점 「난바」. 그러나, 여기에는 「난바」라고 이름이 붙은 역이 6개도 있어, 헤매어 버릴지도 모릅니다. 각각 역이 어디에 있는지, 또 난바역에서 가기 쉬운 관광지 등, 난바역의 정보를 알기 쉽게 정리했습니다!\n\n오사카를 대표하는 터미널 역 중 하나, 난바입니다. 도톤보리와 신사이바시 상점가 등 오사카의 주요 관광지와 가까우며, 또한 관서 국제 공항(KIX)에서는 라피트 특급으로 약 35분이면 도착하여 오사카 관광의 중심지로 매우 편리한 곳입니다.\n\n그러나 난바에는 다양한 전철 노선이 모여 있습니다. 6개의 역이 있고, 대부분이 같은 이름입니다! "현재 어떤 난바 역에 있는지", "목표로 하는 난바 역은 어디인지"를 판단하는 것이 혼란스러울 수 있습니다.\n\n이 기사에서는 6개의 "난바 역"의 차이를 비교하고, 각 역에서 가기 쉬운 관광지 등을 소개합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/20-60982.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60815.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60816.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/17-60817.webp"]'::jsonb, E'2023-11-15'::timestamptz, null),
(E'https://matcha-jp.com/ko/26720', E'ko', 27, E'오디오 가이드 "RUN RUN LEARN"을 들으며 오사카 성 주변을 뛰어다니면서 역사를 배워보세요.', E'오사카성은 오사카에서 가장 유명한 관광 명소 중 하나입니다. 도심 한복판에 자리 잡은 이곳은 역사와 자연이 어우러진 곳으로, 관광 명소일 뿐만 아니라 러닝 코스로도 인기가 높습니다. 오디오 가이드를 통해 "역사를 들으며 달리는" 새로운 경험을 소개해 드리겠습니다.\n\n오사카성은 오사카의 상징입니다. 오사카 관광객들이 꼭 방문해야 할 명소인 오사카성을 거닐다 보면 400년이 넘는 역사의 흔적이 담긴 거대한 석벽과 해자 끝에 우뚝 솟은 장엄한 성문루를 마주하게 됩니다. 이곳은 역사의 낭만이 가득한 공간으로, 오랜 세월 동안 축적된 역사의 숨결을 느낄 수 있는 곳입니다.\n\n오사카성을 방문하면 돌담과 해자를 따라 가볍게 달리는 관광객과 러너들을 만날 수 있습니다. 오사카성은 관광 명소로 유명하지만, 아침저녁으로 많은 러너들이 찾는 인기 러닝 코스이기도 합니다.\n\n오사카 성에서 새로운 경험이 시작되었습니다. 바로 달리면서 역사를 "듣는" 것입니다. 오디오 가이드 "RUN RUN LEARN | 오사카 성 러닝 스루 타임"은 마치 여행 스토리텔러처럼 역사 이야기를 들려주며, 관광 달리기를 더욱 특별하게 만들어 줍니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/02/07-258028.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/07-258029.webp"]'::jsonb, E'2026-02-07'::timestamptz, E'오사카성'),
(E'https://matcha-jp.com/ko/4072', E'ko', 28, E'오사카・교토에서 1시간! 아리마 온천 완벽 가이드! 추천하는 당일치기 온천, 카페, 기념품', E'아리마 온천은 1000년 이상의 역사가 있는 일본에서 가장 오래된 온천입니다. 황금 온천 \'킨센\'과 오래된 거리가 늘어서 있는 온천 거리 등 매력으로 가득한 온천 마을입니다. 오사카, 교토에서도 접근성 편리! 그런 아리마 온천에서 꼭 가봐야할 추천 당일치기 온천, 카페, 기념품 가게 등을 소개합니다!\n\n\'유모토자카\'. 좁지만 이곳이 메인 스트리트 아리마 온천은 효고현에 있는 일본 최고(最古)라 일컬어지는 온천. 1000여 년 전까지 거슬러 올라가는 역사를 지닌 곳입니다.\n\n온천 마을 주위는 사방 1킬로미터로 아담하지만, 그 안에는 온천 숙소와 가게로 가득합니다. 유모토자카라는 언덕길이 메인 스트리트이고, 그 양쪽으로 기념품 가게, 잡화점 등이 늘어서 있습니다. 거기서 옆쪽 샛길로 들어서면 아지트 분위기를 가진 가게도 찾아볼 수 있습니다.\n\n아리마 온천의 매력은 바로 이곳만의 특별한 온천. 그리고 구불구불한 언덕길이 겹쳐지는 온천 거리. 몇 번을 가도 새로운 발견으로 가득한 온천 마을입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/09-60159.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/09-60160.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/12-60349.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/12-60333.webp"]'::jsonb, E'2023-06-20'::timestamptz, E'아리마 온천'),
(E'https://matcha-jp.com/ko/5887', E'ko', 28, E'당알치기・1박2일 여행! 모두 추천합니다! 오사카・교토근교 가고싶은 온천스폿5선!', E'관서지방의 인기 관광지인 오사카, 교토. 모처럼 일본까지 여행왔는데 머스트체크 관광지뿐만 아니라 조금은 여유롭게 온천을 즐기며 몸도 마음도 치유해보세요. 오사카나 교토에서부터 신칸센, 버스를 타고 가벼운 마음으로 다녀올수있는 인기 온천을 소개합니다.\n\n「도쿄, 오사카 관광을 했다면 그 다음에는 온천을 즐기며 힐링하고 싶다!」라 생각하시는 분들에게는 기쁜소식 입니다! 일본의 인기 관광지인 오사카・교토 주변에도 온천, 자연 ,요리를 즐길 수 있는 장소가 있어요!\n\n이번 기사에서는, 오사카나 교토에서부터 신칸센이나 버스를 타고 가벼운 마음으로 방문할 수 있는 인기 온천을 소개합니다.\n\n키노사키 온천(城崎温泉)은 효고현 토요오카시에 있는 1300년의 역사를 자랑하는 온천입니다. 마을에 흐르는 오오타니천(大谿川) 변에는 온천마을이 있고, 강가에는 버들나무와 오래된 목조고택건물이 줄지어 서 있는 정취가 있는 마을입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/15-36213.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/15-50477.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/15-50479.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/15-50481.webp"]'::jsonb, E'2018-12-26'::timestamptz, E'키노사키 오세'),
(E'https://matcha-jp.com/ko/6379', E'ko', 28, E'고베에서 해보고 싶은 열 다섯 가지! 추천 일정과 지역 소개', E'모처럼 간사이를 찾으신다면 오사카, 교토만 방문하기에는 아깝죠! 오사카나 교토에서 교통이 편리한 고베에는 항구도시에서만 볼 수 있는 세련된 분위기의 거리나 멋진 카페, 역사 깊은 건물들이 많이 있습니다. 고베에서는 무엇을 즐길 수 있을지, 철저하게 소개합니다!\n\n고베 (神戸) 라고 하면 여러분은 어떤 것이 떠오르나요? 고베 소고기? 아니면 항구 마을에서의 쇼핑?「오사카나 교토에서 가까운멋스러운 동네」의 이미지가 떠오르는 분들이 많을지도 모르겠네요.\n\n그렇지만, 고베에는 다양한 문화가 조화를 이루는 다채로운 얼굴을 가진 도시입니다. 예로부터 항구도시로써 번성하여 서양의 문화와 일본의 문화가 섞여 탄생한, 세련된 거리 풍경이 여러분을 반깁니다.\n\n그런 한편, 조금만 발을 옮기면 일본에서 가장 오래된 온천・아리마 온천 (有馬温泉)이나 풍부한 자연이 자랑거리인 롯코 지역 (六甲エリア)이 펼쳐집니다. 더욱이, 일본 뒷골목 분위기가 물씬 묻어나는 상점가도 있어요.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/09/04-62018.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/04-62019.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/05-62084.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/05-62085.webp"]'::jsonb, E'2019-03-28'::timestamptz, E'아리마 온천'),
(E'https://matcha-jp.com/ko/7275', E'ko', 29, E'【2023】나라 관광 15선! 세계유산 & 명물 먹거리', E'교토나 오사카에서 당일치기로 갈 수 있는 나라에는 세계유산과 국보로 등록된 신사, 사찰, 에도 시대부터 남아있는 옛 거리 등 매력적인 명소가 많이 있습니다. 이번 기사에서는 \'나라 관광 15선\'을 중심으로 도쿄, 오사카, 교토에서 나라로 가는 방법과 추천 호텔을 소개합니다.\n\n오사카나 교토에 인접한 나라는 지금으로부터 약 1300년 전인 나라 시대(710~784년)에 번성했던 고도(古都)입니다.\n\n일본에서 가장 오래된 불교 건축물 중 하나인 호류지(法隆寺)와 도다이지(東大寺)에 있는 나라 대불 등 일본의 문화와 종교에 관련된 역사적 볼거리가 많습니다.\n\n교토나 오사카에서 당일치기 관광도 가능하니 간사이 지방을 방문한다면 꼭 들러보세요. 이번 기사에서는 \'나라 관광 15선\'과 함께 축제, 교통편 등 나라 관광에 도움이 되는 정보도 함께 소개합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75394.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/23-136247.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75392.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/23-136245.webp"]'::jsonb, E'2023-09-21'::timestamptz, null),
(E'https://matcha-jp.com/ko/1491', E'ko', 29, E'나뭇잎에 쌓인 신기한 스시, 나라 명물「카키노하 스시」란?', E'그런 나라현에「카키노하 스시(柿の葉寿司)」라는 특이한스시가 있다는 것을 아시나요?\n\n나라현(奈良県)은 교토부(京都府)와 오사카부(大阪府)에 인접한 일본 서부 지역에 있는 현이랍니다. 토우다이지(東大寺)나 호우류우지(法隆寺), 카스가 대사(春日大社) 등의 절과 신사가 있는 일본 굴지의 관광지랍니다.\n\n그런 나라현에「카키노하 스시(柿の葉寿司)」라는 특이한 스시가 있다는 것을 아시나요?\n\n한 입 크기로 쥔 쌀밥에 소금에 절인 고등어 사시미를 올려 감나뭇잎(柿の葉/카키노하)로 감쌉니다. 이것을 나무 상자에 넣어 돌의 무게로 압력을 가한 상태로 수일간 발효시키는 것이랍니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/03/17-228239.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/30-127264.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/17-228240.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/17-228241.webp"]'::jsonb, E'2016-01-18'::timestamptz, E'나라시'),
(E'https://matcha-jp.com/ko/333', E'ko', 29, E'아름다운 일본의 세계유산 모음 (1993~1998)', E'일본에는 자금 세계유산이 멏개 있는지 알고 계시나요?(2014년 5월 현재) 문화 유산이 13개, 자연유산이 4개, 합해서 17개의 세계유산이 있습니다. 이번에는 아름다운 일본의 세계유산을 등재년순으로 2기사에 나누었습니다.\n\n이 지역에서 가장 유명한 \'호류지\'는 607년에 세워졌습니다. 1993년에 등록된 ‘호류지 건축물’은 일본에서 최초로 지정된 세계유산입니다. 호키지도 이때 같이 등록되었습니다. 세계에서 가장 오래된 목조건축물에 현시대의 사람들도 줄곧 매료되곤 합니다.\n\n야구시마는 카고시마현 남쪽에 위치하는 아열대지역의 섬이며, 수령 1000년의 역사를 가진 거대한 야쿠 삼나무로 특히 알려져 있습니다. 깊은 숲과 마린 블루의 바다로 둘러 싸인 아주 아름다운 곳, 그런 곳이 야쿠섬입니다.\n\n히메지성은 효고현의 히메야마 및 와시야마 위에 축조되어 있는 성이며, 일본은 대표하는 전형적인 방호건축으로 알려져 있습니다. 그 아름답게 빛나는 하얀 성벽은 일본의 긴 역사를 거치고도 변함없이 그곳에 있습니다. 뛰어난 방어력은 지금도 성곽의 아름다운 풍경과 눈을 끄는 매력을 지켜주고 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126602.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126594.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126601.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126595.webp"]'::jsonb, E'2014-05-04'::timestamptz, E'지정'),
(E'https://matcha-jp.com/ko/25844', E'ko', 30, E'고야산 1일 개인 가이드 투어 | 세계문화유산 고야산 샘플 일정', E'오사카에서 기차와 케이블카를 타고 세계문화유산인 고야산을 하루 만에 탐험해 보세요. 오전에는 고야산의 관문인 다이몬몬, 진언밀교의 중심지인 단조가란, 그리고 총본산인 곤고부지 절을 방문합니다. 오후에는 도쿠가와 가문의 능묘를 방문하고, 마지막으로 고야산 최대의 명소인 오쿠노인을 방문합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/17-244585.webp"]'::jsonb, E'2025-09-27'::timestamptz, E'고야산'),
(E'https://matcha-jp.com/ko/2033', E'ko', 30, E'【폐허】마치 라퓨타 세계! 와카야마현 토모가시마(友ヶ島) 「제3 포대 유적」', E'<strong>스튜디오 지브리</strong>의 『<strong>천공의 섬 라퓨타</strong>』는 일본의 TV방송으로 재방영 될 정도로 인기 있는 영화랍니다. 그런 『천공의 섬 라퓨타』의 세계관을 느낄 수 있는 무인도가 <strong>와카야마현(和歌山県)</strong>에 있답니다!! 그곳이 바로, 이번에 소개해 드릴 「<strong>토모가시마(友ヶ島)</strong>」에요.\n\n스튜디오 지브리의 『천공의 섬 라퓨타』는 일본의 TV방송으로 재방영 될 정도로 인기 있는 영화랍니다. 그런 『천공의 섬 라퓨타』의 세계관을 느낄 수 있는 무인도가 와카야마현(和歌山県)에 있답니다!!\n\n토모가시마로 가는 방법은 배편 말곤 없답니다. 우선은 와카야마현 와카야마시의 카다 항(加太港)까지 가야 해요. 와카야마시 중심부에서 타다 항까지 가려면, 먼저 난카이 전철 카다선(南海電鉄加太線)을 타고 와카야마시역에서 카다역까지 오셔야 해요. 그리고 걸어서 15분 정도면 도착이에요. 항구 가까이에 다다랐다면 토모가시마 행 안내가 보인답니다.\n\n승선 티켓은 이곳에서 사셔야 해요. 정원에 달하면 탈 수 없는 경우도 있으니 일찍 가시는 것이 좋을 거예요. 요금은 어른 왕복 2,000엔, 아이는 왕복 1,000엔이에요.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123462.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123463.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123464.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123465.webp"]'::jsonb, E'2016-08-26'::timestamptz, E'와카야마시'),
(E'https://matcha-jp.com/ko/5175', E'ko', 31, E'돗토리 다이센 산의 추천 관광코스! 풍경, 먹방, 절, 미술관 즐기기', E'돗토리현의 인기 관광지인 다이센 산은 다채로운 액티비티를 즐길 수 있는 것은 물론 아름다운 풍경과 절, 미술관, 먹거리도 가득합니다. 본 기사에서는 계절별 다이센 산의 매력과 편리한 교통, 저렴한 관광버스인 「다이센 루프 버스」를 이용한 강력추천 1일 관광 코스를 소개합니다.\n\n돗토리현 서부에 위치한 다이센 산(大山)은 1,729미터 높이로 주고쿠 지방에서 가장 높은 봉우리 입니다. 일본의 국영방송(NHK)이 실시한 일본 명봉 랭킹에서는 후지산과 야리가타케(槍ヶ岳)에 이어 베스트 3위로 선정되었습니다.\n\n봄・여름에는 신록, 가을엔 단풍, 겨울에는 눈으로 뒤덮힌 아름다운 경관과 함께 옛부터 신이 사는 산으로서 지역 사람들에게 신성한 산으로 여겨져왔습니다. 현재는 절경과 사적, 먹거리, 액티비티를 즐길 수 있는 인기 관광지로서 친숙한 곳입니다.\n\n다이센 산에서는 봄부터 가을까지 하이킹과 사이클링,캠프,승마등이 가능합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/10/11-38320.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/11-38322.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/10-38221.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39440.webp"]'::jsonb, E'2018-07-02'::timestamptz, E'모우 다이세'),
(E'https://matcha-jp.com/ko/5396', E'ko', 31, E'돗토리현에 온다면 꼭 먹어야하는 추천 먹거리! -해산물, 와규, 디저트, 라면 등-', E'초밥, 라면 등 맛있는 음식이 많은 일본. 일본 내에서도 돗토리현은 "맛의 고장(食のみやこ)" 이라고 불리울 정도로 맛있는 먹거리들이 가득한 보물창고 입니다. 돗토리현의 여러가지 맛있는 음식들 중에서 엄선한 해산물과 와규, 디저트, 라면, 카레라이스를 소개합니다.\n\n돗토리현에는 홍게(ベニズワイガニ)와 참다랑어(マグロ)의 수확량이 일본에서 가장 많은 사카이 항(境港)과 돗토리시 중심부에서도 가까운 돗토리 항(鳥取港)등의 어항이 있습니다. 그래서 현내의 많은 음식점에서 신선한 해산물을 합리적인 가격으로 즐길 수 있습니다.\n\n돗토리현에는 바위굴(イワガキ)나 도루묵(ハタハタ), 진흙새우(モサエビ), 한치(シロイカ)등 맛있는 해산물이 가득합니다. 그 중에서도 인기 있는 해산물은 11월부터 2월이 제철인 “마쓰바 대게(松葉ガニ)". 높은 품격이 느껴지는 맛있는 살이 꽉 차있어 충분한 포만감을 느낄 수 있습니다.\n\n“마쓰바 대게”는 회덮밥(海鮮丼/카이센동)이나 초밥(寿司/스시), 게전골(カニ鍋/카니나베)등의 다양한 방법으로 즐길 수 있습니다. 예를 들면 사카이 미나토시(境港市)의 미즈키 시게루 로드(水木しげるロード) 가까이에 있는 음식점 “고항야 이사리비(ご飯や漁火)“에서는, 겨울이 되면 마쓰바 대게 한마리가 통채로 얹어져있는 “마쓰바 대게 덮밥(松葉ガニ1杯まるごと丼)“을 먹을 수 있습니다. 이외에도 JR 돗토리역 근처의 돗토리 항구 수산시장(鳥取港海鮮市場) “가로이치(かろいち)” 주변에 있는 음식점에서도 갓 잡아올린 신선한”마쓰바 대게”를 맛볼 수 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/20-41948.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/11-43567.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/20-41950.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/11-43568.webp"]'::jsonb, E'2018-03-20'::timestamptz, E'돗토리시'),
(E'https://matcha-jp.com/ko/5602', E'ko', 31, E'일본에서 가장 아름다운 별을 볼 수 있는 곳. 멋진 경치를 찾는 분께 추천하는 나이트 투어&숙박지 in 돗토리', E'일본에는 아름다운 밤하늘을 감상할 수 있는 곳이 많아요. 그중에서도 돗토리현의 여름철은 어느 곳에서나 은하수를 볼 수 있어 「일본에서 가장 아름다운 별을 볼 수 있는 지역」이라 불리고 있죠. 밤하늘 투어 정보와 모닥불 그리고 반딧불이까지 즐길 수 있는 숙박지를 소개합니다.\n\n그리스 신화 속 전설에서 보듯 사람은 예로부터 별을 보며 신비로운 생각을 했습니다.\n\n일본에도 중국에서 전해진 칠석(七夕)에 얽힌 전설이 있지요. 서로를 그리워하는 거문고자리의 베가(직녀성)와 독수리자리의 알타이르(견우성)가 1년에 한 번, 7월 7일에만 만난다는 러브스토리입니다.\n\n여러분도 일본에 오시면 신비로운 분위기에서 밤하늘을 올려보는 게 어떨까요?', E'["https://resources.matcha-jp.com/resize/720x2000/2018/01/04-45233.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/19-46367.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/04-45234.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/04-45238.webp"]'::jsonb, E'2018-03-20'::timestamptz, null),
(E'https://matcha-jp.com/ko/8269', E'ko', 32, E'호시노리조트 타마츠쿠리――인연을 맺어주는 땅에서 특별한 시간을 즐기자', E'‘호시노리조트 카이 이즈모\'는 시마네현의 유명한 다마쓰쿠리온천에 자리한 쾌적한 료칸입니다. 이곳에 묵으면 일본 신화의 무대, 신들이 숨쉬는 땅을 피부로 느낄 수 있을 것입니다.\n\n이즈모는 현재 시마네현의 옛 이름으로, 일본에서 가장 오래된 역사서 “고지키"에 나오는 일본 신화의 무대입니다. 11월에는 일본 유수의 신사인 이즈모타이샤에 전국의 신들이 모인다고 합니다.\n\n또한 이곳을 방문하는 사람은 공사 모두 좋은 인연을 만난다하여 ‘인연을 맺어주는 땅\'으로도 불립니다.\n\n일본에서 가장 오래된 온천 중 하나로 알려진 다마쓰쿠리온천에 문을 연 ‘호시노리조트 타마츠쿠리 ’는 일본 신화의 세계관을 느끼며 머무를 수 있는 숙박시설입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/12/05-92395.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92578.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92581.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92582.webp"]'::jsonb, E'2019-12-25'::timestamptz, null),
(E'https://matcha-jp.com/ko/11842', E'ko', 33, E'서일본 최대급! 이온몰 오카야마의 추천 가게를 소개합니다!', E'JR 오카야마역 앞에 있는 \'이온몰 오카야마\'는 서일본에서 가장 큰 규모의 이온 그룹 쇼핑몰입니다. 많은 점포가 면세점을 운영하고 있으며, 오카야마 특유의 상품도 풍부합니다. 기념품, 의류, 잡화를 구입하거나 현지 음식을 즐기기에 안성맞춤인 곳입니다.\n\n\'이온몰 오카야마\'는 JR 오카야마역 고라쿠엔(後楽園) 출구에서 지하도로 바로 연결되어 있어 쉽게 갈 수 있습니다.\n\nJR 오카야마역의 동쪽 출구로 나가서 오른쪽으로 꺾으면 바로 이온몰의 간판을 볼 수 있습니다.\n\n\'이온몰 오카야마\'는 히로시마 인근을 포함한 주고쿠(中国) 지방에서 가장 큰 규모의 쇼핑몰로, 약 300개의 점포가 입점해 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/05/23-138451.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136380.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136381.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136383.webp"]'::jsonb, E'2023-06-02'::timestamptz, null),
(E'https://matcha-jp.com/ko/3816', E'ko', 33, E'오카야마시의 관광지 5선 (오가야마 고라쿠엔/오가야마성/이즈시쵸/키비츠히코 신사/노면 전차)', E'오카야마현 오카야마시는 츄고쿠 지방에 포함되는 도시예요. 오카야마시는 오사카나 히로시마 등 세계적으로도 유명한 관광지의 중간 지점에 있어서, 일본의 서부 지역을 돌아볼 때의 거점으로도 추천하는 도시중 하나랍니다. 물론, 오카야마시 그 자체로도 매력적인 관광지가 많이 있는데요, 이번 기사에서는 그 중에서도 해외에서 일본에 방문하시는 여러분들께 추천해 드리는 대표적인 관광지 5곳을 골라 보았어요. 일본 정원부터 성, 신사와 오래된 일본 거리의 풍경을\n\n물론, 오카야마시 그 자체로도 매력적인 관광지가 많이 있는데요, 이번 기사에서는 그 중에서도 해외에서 일본에 방문하시는 여러분들께 추천해 드리는 대표적인 관광지 5곳을 골라 보았어요. 일본 정원부터 성, 신사와 오래된 일본 거리의 풍경을 보고 체험할 수 있는 다양한 매력을 가진 오카야마시를 소개해 드릴게요!\n\n오카야마 고라쿠엔은 일본의 3대 정원중 하나로 꼽히는 곳으로, 미슐랭 가이드에서도 별 3개를 인정 받았어요. 만들어진 것은 무려 300년 전으로,ss에도시대이라고 불리던 시대랍니다. 당시 오가야마를 통치하고 있던 이케다 가문의 당주인 츠나마사가 스스로를 위한 힐링 스팟으로써 만들었답니다.\n\n그 당시에는 역대 당주 뿐만 아니라, 허가가 있다면 평민들도 정원 안에 들어갈 수 있었다고 해요. 오랜 옛날부터 오카야마의 사람들에게 사랑받아온 정원이라고도 할 수 있겠네요.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/05-13147.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/05-13149.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/05-13150.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/05-13155.webp"]'::jsonb, E'2017-01-26'::timestamptz, E'오카야마시'),
(E'https://matcha-jp.com/ko/6362', E'ko', 33, E'【오카야마】청명한 고장을 즐겨보자! 오카야마・구라시키 "연애성취&과일 여행"', E'과일 생산이 활발한 오카야마현은 "과일 왕국"이라 불리고 있어요. 이번 기사에는 맛있는 과일에 입맛 다시며 연애성취의 신사를 돌아보는 비장의 여행지를 소개합니다! 달콤하고 즐거운 오카야마 여행을 떠나볼까요?\n\n일본의 주고쿠지방(中国地方)에 위치한 "청명한 고장" 오카야마현은 온난한 기후와 긴 일조시간으로 과일 재배에 이상적인 환경을 갖추고 있어요. 맛있는 과일 산지로 알려진 오카야마현은 "과일 왕국"이라 불리고 있답니다. 당도, 향기, 풍미가 뛰어난 오카야마의 과일은 그야말로 "삼고 과일"이지요.\n\n오카야마현에는 맛있는 과일 외에도 아름다운 경치와 연애성취에 효험있는 신사가 있어 관광을 즐길 수 있어요. 이번 기사에는 MATCHA 편집부가 오카야마시(岡山市)와 구라시키시(倉敷市)의 맛있는 과일과 인기있는 연애성취 스폿을 소개할게요! 연애성취와 달콤한 과일 여행으로 출발해 봅시다!\n\n오카야마현의 남쪽에 있는 오카야마시는 일본 100대 명성 중 하나인 "오카야마성(岡山城)"과 일본 3대 명원 중 하나인 "고라쿠엔(後楽園)"이 있는 관광지예요. 이 두 곳의 관광지를 둘러본 다음 앞으로 소개할 연애성취에 효험있는 두 곳의 사원으로 전철을 타고 이동해 봅시다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59162.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59163.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59146.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/02-59766.webp"]'::jsonb, E'2018-08-24'::timestamptz, E'오카야마시'),
(E'https://matcha-jp.com/ko/11239', E'ko', 34, E'히로시마의 2대 쇼핑 명소 《THE OUTLETS HIROSHIMA》와 《이온몰 히로시마 후츄》! 그 인기의 비밀을 파헤치다', E'히로시마 인기 쇼핑 명소 《THE OUTLETS HIROSHIMA》와《이온몰 히로시마 후츄》. 브랜드 제품은 물론 생활용품도 저렴하게 구입할 수 있으며 놀거리 시설도 충실하여 관광객과 히로시마 현지인 모두에게 추천하는 곳입니다. 이 2대 쇼핑 명소의 매력에 대해 소개합니다!\n\n세계 유산인 이쓰쿠시마 신사나 원폭 돔으로 유명한 히로시마. 이 유명 관광지에서 특히 인기 있는 쇼핑 명소가 바로 《THE OUTLETS HIROSHIMA》와《이온 몰 히로시마 후츄》입니다.\n\n양쪽 모두 JR히로시마역에서 쉽게 이동할 수 있으며 저렴하고 합리적인 쇼핑은 물론 즐길거리 역시 다양하게 마련되어 있습니다.\n\n이번 기사에서는 이 양대 쇼핑 명소가 각각 어떤 특징이 있는지에 관해 소개 드립니다. 히로시마로 관광을 오시는 분들도, 히로시마 주변에 거주하시는 현지인분도 이번 기사를 읽고 히로시마의 쇼핑을 한층 더 즐겨보세요!', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127864.webp","https://resources.matcha-jp.com/resize/720x2000/2023/04/19-137288.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127865.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127866.webp"]'::jsonb, E'2022-07-14'::timestamptz, null),
(E'https://matcha-jp.com/ko/3219', E'ko', 34, E'히로시마에서 꼭 가야하는 관광 스폿 22선과 추천 지역 음식 6선', E'히로시마현이란 일본 츄고쿠 지방에 위치한 지역으로, 이쿠츠시마 신사가 있는 미야지마, 원폭 돔, 사이클링 로드 등으로도 알려진 시마나미 해도 등의 많은 관광 스폿이 있는 지역이에요. 이 기사에서는, 히로시마에 가는 방법, 구역별 설명, 관광 스폿 22선에 음식 정보까지! 히로시마 여행에 필요한 정보를 모아 보았습니다.\n\n히로시마현(広島県)이란, 일본의 츄고쿠 지방(中国地方)에 위치해 있으며 서쪽은 세토우치 해(瀬戸内海), 동쪽부터 북쪽까지는 산에 감싸인 자연이 풍부한 현이랍니다. 제2차 세계 대전 이전부터 공업과 산업, 상업으로 번영했으며 지금도 츄(中)・시코쿠 지방(四国地方) 최대의 도시로 알려져 있답니다.\n\n또, 1945년 8월 6일에 미군이 일본 히로시마 시에 최초로 핵병기를 투하하여 심대한 피해를 일으킨 사실도 유명하지요. 현재의 폭심지는 히로시마 평화 기념 공원으로 정비되어 일본을 대표하는 사적(史跡)이 되었어요.\n\n히로시마풍 오코노미야키나 쿠레 얇은 우동(呉細うどん), 도미 밥 등의 음식도 유명한 히로시마. 그런 히로시마의 매력을 충분히 즐기기 위해 알아두면 좋은 것들을 정리했습니다.', E'["https://resources.matcha-jp.com/archive_files/jp/2016/09/plane.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/bullet-train.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/DSC01521.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/hirosima3_20160823h.webp"]'::jsonb, E'2017-03-28'::timestamptz, E'미야지마'),
(E'https://matcha-jp.com/ko/26999', E'ko', 34, E'히로시마를 깊이 있게 경험할 수 있는 네 가지 체험 여행 | 역사, 음식, 문화를 담은 여행 가이드', E'이 글에서는 히로시마의 역사, 음식, 문화를 다채로운 시각으로 즐길 수 있는 네 가지 체험형 투어를 소개합니다. 평화 교육부터 야간 음식 투어, 미야지마 섬의 전통 문화 체험까지, 더욱 풍성한 여행을 만들어 줄 매력적인 요소들을 전해드립니다.\n\n최근 들어 현지 가이드와 함께 직접 배우고, 맛보고, 느끼며 깊이 있게 체험할 수 있는 \'체험형 투어\'가 특히 인기를 얻고 있습니다. 예를 들어 평화기념공원과 원폭 돔을 둘러보는 도보 투어를 통해 히로시마의 역사에 대해 배우고, 복구 과정과 평화를 향한 노력을 직접 경험할 수 있습니다.\n\n이 글에서는 히로시마의 매력을 다양한 관점에서 경험할 수 있는 엄선된 네 가지 여행 상품을 소개합니다.\n\n이 투어는 유네스코 세계문화유산으로 등록된 평화기념공원과 평화기념박물관 등 중요한 장소를 방문하여 히로시마의 과거와 평화의 메시지를 더욱 깊이 이해할 수 있도록 해줍니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261781.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261795.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261796.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261783.webp"]'::jsonb, E'2026-03-28'::timestamptz, E'미야지마'),
(E'https://matcha-jp.com/ko/1603', E'ko', 35, E'【절경】일본에서 가장 새전하기 힘든 신사, 야마구치「모토노 스미이나리 신사(元乃隅稲成神社)」', E'이번에는, 새전 하는 것이 가능하면 소원이 이루어진다고 전해지는「<strong>모토노 스미이나리 신사(元乃隅稲成神社)</strong>」를 세계에서 인정하는 절경과 함께 소개해 드립니다.\n\n일본 신사에서는 새전(賽銭)을 해서 소원을 비는 방법이 정번입니다. 보통은 동전을 전용 상자에 던져 넣기만 하면 되지만, 개중에는 새전만 해도 엄청 고생하는 신사가 있답니다.\n\n모토노 스미이나리 신사(元乃隅稲成神社)가 있는 곳은 바다와 산 등의 자연이 풍부한 야마구치현(山口県) 나가토시(長門市)입니다. 신사가 만들어진 계기는 1955년까지 거슬러 올라간답니다. 지역 어부의 꿈에 하얀 여우가 나타나「나를 모시는 신사를 만들거라」고 계시를 내리고 간 것이 계기라고 합니다.\n\n시마네현(島根県)에 있는 타이코다니 이나리 신사(太鼓谷稲成神社)에서 분령(分霊：신의 영혼을 나누는 것)된 곳으로 지금은 상업 번영과 개운 제액・교통 안전 등의 여러 소원을 이루어주는 신으로써 모셔지고 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123262.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123263.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123264.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123265.webp"]'::jsonb, E'2016-02-12'::timestamptz, E'나가토시'),
(E'https://matcha-jp.com/ko/22897', E'ko', 36, E'야간 미술관 대절! 레오나르도 다빈치의 \'최후의 만찬\' 앞에서 로컬 생산 디너를 즐기다', E'도쿠시마현의 오츠카 국제 미술관에서, 레오나르도 다빈치의 최후의 만찬을 감상하면서 디너를 먹을 수 있는 체험이 개최됩니다. 2024년 12월 13일(금)과 2025년 1월 31일(금) 이틀 한정입니다. 이번 기사에서는 체험 상세 내용 및 예약 방법 등을 소개합니다.\n\n도쿠시마현 나루토시에 있는 오츠카 국제 미술관은 세계의 명화를 도판(※)으로 재현한 도판 명화를 전시한 미술관입니다.\n\n고대 벽화에서부터 현대 회화에 이르기까지 서양 명화 1,000여 점을 전시하고 있습니다. 일본 안에서 전 세계 명화를 감상할 수 있는 장소입니다.\n\n그런 오츠카 국제 미술관에서, 레오나르도 다빈치의 최후의 만찬 바로 앞에서 디너를 즐기는 사상 초유의 시도가 펼쳐집니다. 전관을 대절하여 현지의 식재료를 아낌없이 사용한 디너 코스를 즐길 수 있는 프리미엄 체험입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/24-211767.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/24-211773.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/09-214028.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/24-211770.webp"]'::jsonb, E'2024-12-10'::timestamptz, E'나루토시'),
(E'https://matcha-jp.com/ko/6762', E'ko', 36, E'도쿠시마현 (徳島県)・니시아와 (にし阿波) 에서 400년 전으로 시간여행을', E'400년의 사람들의 생활히 고스란히 남아있는 도쿠시마현 (徳島県) 서부의「니시아와 (にし阿波)」. 이 지역 사람들은 생활에 필요한 농업을 경사도가 최대 40도나 되는 농지에서 하고 있습니다. 상인의 동네로써 번영했던「우다츠노마치나미 (うだつの町並み)」도, 옛 일본의 모습이 남아있는 동네. 이번에는 현대의 생활과는 조금 다른 체험을 해 볼 수 있는 니시아와 지구의 매력을 소개합니다.\n\n일본의 서부, 시코쿠지방 (四国地方)에 있는 도쿠시마현 (徳島県)은, 1586년 부터 이어져온다고 전해지는 여름 축제 (마츠리)「아와오도리 (阿波おどり)」나, 세계 삼대 조류로도 불리는「 나루토의 소용돌이 (鳴門の渦潮)」, 츠루기산 (剣山) 이나 히잔 (眉山) 을 시작으로한 산 등, 일본의 전통과 자연을 느낄 수 있는 장소. 메이지시대 (明治時代) 이전에 이 지역은 아와「아와 (阿波)」라고 불리어, 지금도 그 이름이 곳곳에 남아 있습니다.\n\n이번에는 도쿠시마현에서도 세계농업유산(※1) 으로 지정된「니시아와 (にし阿波)」의 매력을 알아봅니다.\n\n※1：세계농업유산……UN식량농업기구(FAO)가 인정하는, 세계적으로 중요 및 전통적인 농림수산업을 행하는 지역. 세계 21개국 25개 지역이 인정되고 있다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65683.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65666.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/06-65911.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65667.webp"]'::jsonb, E'2018-12-10'::timestamptz, E'나루토 히오오'),
(E'https://matcha-jp.com/ko/4203', E'ko', 36, E'일본 최후의 비경에서 진정한 시골 생활을 체험하다. 도쿠시마 현의 농림어가 민박(農林漁家民宿)', E'일본만의 문화를 체험하고 싶어, 시골 분위기가 물씬 풍기는 공간에서 여유로운 시간을 보내고 싶어. 그런 생각을 하신다면 "농림어가 민박(農林漁家民宿)"에 묵어 보시는 건 어떤가요? 도쿠시마현의 「농림어가 민박」이라면 모내기와 산나물 캐기, 후릿그물 어법 등의 농림어업 체험은 물론, 지역 주민들과 가족처럼 접하며 일본 시골의 자연과 절경을 만끽할 수 있어요.\n\n일본만의 문화를 체험하고 싶다. 시골 분위기가 물씬 풍기는 공간에서 여유로운 시간을 보내고 싶다. 지금까지와는 다른 독특한 여행을 해보고 싶다.\n\n그런 분들은 농림어가 민박(農林漁家民宿)에 가보시면 어떨까요? 도시와 달리 여유로운 장소에서 일본에서 오래 이어져 온 생활을 체험할 수 있답니다!\n\n※농림어가 민박(農林漁家民宿)은 자치체와 시설에 따라 명칭, 조건과 기준 등이 다릅니다. 본 기사에서는, 도쿠시마 현(徳島県)의 농림어가 민박에 한정하여 소개해 드립니다. 자세한 사항은 각 시설에 문의해 주세요. ※제공하는 서비스와 설비는 시설에 따라 다릅니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/23-22071.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/23-22072.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/23-22073.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/23-22074.webp"]'::jsonb, E'2017-05-02'::timestamptz, E'도쿠시마시'),
(E'https://matcha-jp.com/ko/7360', E'ko', 37, E'【가가와】 일본 최고의 일몰 명소! 세토나이카이 ・ 치치부가하마의 다섯 가지 즐기는 법', E'카가와현 서부의 미토요시에 있는 치치부가하마는 일본 최고의 석양을 즐길 수 있는 절경 명소로 유명합니다. 하지만 여기에 있는 것은 절경 뿐만 아닙니다. 카약이 있는 명소와 현지 음식을 즐길 수 있는 카페, 멋진 게스트 하우스와 기념품 가게도 있습니다!\n\nPicture coutesy of 三豊市(미토요시) 카가와현 서부의 미토요시에 있는父母ヶ浜(치치부가하마)는 2016년 이후 SNS를 통해 인기를 끌고 있는 절경 명소. 특히 저녁은에는 아름다운 경관을 볼 수 있어서 일본의 주요 여행 잡지에서 2018년에 ‘가고 싶은 석양 절경 랭킹’ 1위를 차지했습니다.\n\n이 절경의 비밀은 썰물 때 모래 사장에 있는 조수 웅덩이에 있습니다. 바람이 약한 날은 조수 웅덩이의 물이 거울과 같아서 하늘을 아름답게 비추고 있습니다.\n\n조수 웅덩이는 바위에 있는 경우가 많는데, 치치부가하마에서는 모래 사장에 큰 조수 웅덩이가 있습니다. 이러한 특수성이 기적의 절경을 만들어 내고 있는 것입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76985.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76989.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76986.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76987.webp"]'::jsonb, E'2019-06-19'::timestamptz, E'미토요시')
